 const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
+const dynamicValidators = new WeakMap<object, ValidateFunction>();
+
+function getDynamicValidator(definition: ToolDefinition): ValidateFunction {
+  const cached = dynamicValidators.get(definition.inputSchema);
+  if (cached) {
+    return cached;
+  }
+  const compiled = compileSchema(definition.name, definition.inputSchema);
+  dynamicValidators.set(definition.inputSchema, compiled);
+  return compiled;
+}

 function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
   try {
     return ajv.compile(schema);
   } catch (error) {
-    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`);
+    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {cause: error});
+  }
+}
+
+function formatValidationError(errors: ErrorObject[] | null | undefined): string {
+  if (!errors || errors.length === 0) {
+    return 'Input validation failed';
   }
+  return errors
+    .map(err => {
+      const path = err.instancePath.replace(/^\//, '').replace(/\//g, '.');
+      if (err.keyword === 'required') {
+        const prop = (err.params as {missingProperty?: string}).missingProperty;
+        const field = path ? `${path}.${prop}` : (prop ?? 'unknown');
+        return `Missing required property: ${field}`;
+      }
+      const field = path || 'input';
+      if (err.keyword === 'type') {
+        const expected = (err.params as {type?: string}).type;
+        return `Property "${field}" must be of type ${expected}`;
+      }
+      if (err.keyword === 'enum') {
+        const allowed = (err.params as {allowedValues?: unknown[]}).allowedValues;
+        return `Property "${field}" must be one of: ${JSON.stringify(allowed)}`;
+      }
+      return `Property "${field}" ${err.message ?? 'is invalid'}`;
+    })
+    .join('; ');
 }
